    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) {
      continue
    }
    const tokens = splitLine(trimmed)
    const word = tokens[0]

    try {
      if (word === 'bucket' || word === 'window' || word === 'route') {
        if (eventSeen) {
          throw new Error('declarations must come before the first event')
        }
        if (word === 'bucket') {
          if (tokens.length !== 5) {
            throw new Error('expected bucket <name> <capacity> <refill> <per>')
          }
          const [, name, capacityTok, refillTok, perTok] = tokens
          if (!NAME_RE.test(name)) {
            throw new Error(`invalid policy name ${name}`)
          }
          if (policies.has(name)) {
            throw new Error(`policy ${name} is declared twice`)
          }
          const capacity = validateInt(capacityTok, 'capacity', 1n)
          const refill = validateInt(refillTok, 'refill', 0n)
          const per = validateInt(perTok, 'per', 1n)
          policies.set(name, { type: 'bucket', name, capacity, refill, per })
        } else if (word === 'window') {
          if (tokens.length !== 4) {
            throw new Error('expected window <name> <limit> <span>')
          }
          const [, name, limitTok, spanTok] = tokens
          if (!NAME_RE.test(name)) {
            throw new Error(`invalid policy name ${name}`)
          }
          if (policies.has(name)) {
            throw new Error(`policy ${name} is declared twice`)
          }
          const limit = validateInt(limitTok, 'limit', 0n)
          const span = validateInt(spanTok, 'span', 1n)
          policies.set(name, { type: 'window', name, limit, span })
        } else {
          if (tokens.length < 3) {
            throw new Error('expected route <prefix> <policy>...')
          }
          const prefix = tokens[1]
          if (!NAME_RE.test(prefix)) {
            throw new Error(`invalid route prefix ${prefix}`)
          }
          if (routes.has(prefix)) {
            throw new Error(`prefix ${prefix} is routed twice`)
          }
          const policyNames = tokens.slice(2)
          for (const pn of policyNames) {
            if (!policies.has(pn)) {
              throw new Error(`unknown policy ${pn}`)
            }
          }
          routes.set(prefix, policyNames)
        }
      } else if (word === 'event') {
        if (tokens.length !== 3) {
          throw new Error('expected event <tick> <key>')
        }
        const [, tickTok, key] = tokens
        const tick = validateInt(tickTok, 'tick', 0n)
        if (!NAME_RE.test(key)) {
          throw new Error(`invalid key ${key}`)
        }
        if (lastTick !== null && tick < lastTick) {
          throw new Error(`tick ${tick} is before tick ${lastTick}`)
        }
        lastTick = tick
        eventSeen = true
        events.push({ tick, key, line: lineNumber })
      } else {
        throw new Error(`unknown directive ${word}`)
      }
    } catch (err) {
      throw new LineError(lineNumber, err.message)
    }
  }

  return { policies, routes, events }
}
"}

