export class TokenBucketPolicy {
  constructor({ name, capacity, refill, per }) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.cap = capacity * per
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { tokens: this.cap, lastTick: tick }
      this.states.set(key, state)
      return
    }
    if (tick > state.lastTick) {
      const delta = tick - state.lastTick
      const added = this.refill * delta
      let tokens = state.tokens + added
      if (tokens > this.cap) tokens = this.cap
      state.tokens = tokens
      state.lastTick = tick
    }
  }

  allow(key) {
    const state = this.states.get(key)
    return state.tokens >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.tokens -= this.per
  }
}

export class SlidingWindowPolicy {
  constructor({ name, limit, span }) {
    this.name = name
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { queue: [] }
      this.states.set(key, state)
    }
    const threshold = tick - this.span
    while (state.queue.length > 0 && state.queue[0] <= threshold) {
      state.queue.shift()
    }
  }

