 * Runs the parsed events through the declared policies and routes,
 * producing one verdict per event.
 */
import { TokenBucketPolicy, SlidingWindowPolicy } from './policies.js'

function buildPolicyInstances(policies) {
  const instances = new Map()
  for (const [name, def] of policies) {
    if (def.type === 'bucket') {
      instances.set(name, new TokenBucketPolicy(def))
    } else {
      instances.set(name, new SlidingWindowPolicy(def))
    }
  }
  return instances
}

function findRoute(routes, key) {
  let best = null
  for (const prefix of routes.keys()) {
    if (key.startsWith(prefix)) {
      if (best === null || prefix.length > best.length) {
        best = prefix
      }
    }
  }
  return best
}

export function simulate({ policies, routes, events }) {
  const instances = buildPolicyInstances(policies)
  const results = []

  for (const event of events) {
    const { tick, key } = event
    const prefix = findRoute(routes, key)
    if (prefix === null) {
      results.push({ tick, key, allow: true, deniedBy: null })
      continue
    }
    const policyNames = routes.get(prefix)
    const involved = policyNames.map((name) => instances.get(name))

    for (const policy of involved) {
      policy.advance(key, tick)
    }

    let deniedBy = null
    for (let i = 0; i < involved.length; i++) {
      if (!involved[i].allow(key)) {
        deniedBy = policyNames[i]
        break
      }
    }

    if (deniedBy === null) {
      for (const policy of involved) {
        policy.record(key, tick)
      }
      results.push({ tick, key, allow: true, deniedBy: null })
    } else {
      results.push({ tick, key, allow: false, deniedBy })
    }
  }

  return results
}
"}

